<script setup lang="ts">
import{computed,nextTick,onMounted,onUnmounted,ref,watch}from'vue';
import{defaultCameraRaw,validateCameraRaw}from'../../../packages/comp-bridge/camera-raw-settings.mjs';
import{cameraRawAutoWhiteBalance,cameraRawWhiteBalance,cameraRawSample,cameraRawCurveTables}from'../../../packages/comp-bridge/camera-raw.mjs';
const props=defineProps<{value:any;language:string;source?:any;preview?:any;options:any}>(),emit=defineEmits(['refresh']);
const zh=computed(()=>props.language==='zh-Hans'),group=ref('light'),channel=ref('rgb'),family=ref(0),point=ref(0),replacePoint=ref(false),wheel=ref('shadows'),before=ref(false),sampleMode=ref('whiteBalance'),scopeMode=ref('histogram'),display=ref<HTMLCanvasElement>(),scope=ref<HTMLCanvasElement>(),readout=ref(''),error=ref('');
const groups=[['light','Light','明亮度'],['color','Color','颜色'],['effects','Effects','效果'],['curve','Curve','曲线'],['mixer','Color Mixer','颜色混合'],['grading','Color Grading','分色'],['detail','Detail','细节'],['optics','Optics','光学'],['geometry','Geometry','几何'],['calibration','Calibration','校准']];
const fields:Record<string,string[]>={light:['exposure','contrast','highlights','shadows','whites','blacks'],color:['temperature','tint','vibrance','saturation'],effects:['texture','clarity','dehaze','glow','glowRange','glowSpread','glowWarmth','vignetteAmount','vignetteMidpoint','vignetteRoundness','vignetteFeather','vignetteHighlights','grainAmount','grainSize','grainRoughness'],curve:['shadows','darks','lights','highlights','shadowSplit','darkSplit','lightSplit','refineSaturation'],detail:['sharpenAmount','sharpenRadius','sharpenDetail','sharpenMasking','noiseLuminance','noiseLuminanceDetail','noiseLuminanceContrast','noiseColor','noiseColorDetail','noiseColorSmoothness'],optics:['profileDistortion','profileVignetting','distortion','purpleAmount','purpleHueLow','purpleHueHigh','greenAmount','greenHueLow','greenHueHigh','vignetteAmount','vignetteMidpoint'],geometry:['vertical','horizontal','rotate','aspect','scale','offsetX','offsetY'],calibration:['shadowTint','redHue','redSaturation','greenHue','greenSaturation','blueHue','blueSaturation']};
const chinese:Record<string,string>={exposure:'曝光',contrast:'对比度',highlights:'高光',shadows:'阴影',whites:'白色',blacks:'黑色',temperature:'色温（相对值）',tint:'色调',vibrance:'自然饱和度',saturation:'饱和度',texture:'纹理',clarity:'清晰度',dehaze:'去雾',glow:'辉光',glowRange:'辉光范围',glowSpread:'辉光扩散',glowWarmth:'辉光暖色',vignetteAmount:'暗角数量',vignetteMidpoint:'暗角中点',vignetteRoundness:'暗角圆度',vignetteFeather:'暗角羽化',vignetteHighlights:'暗角高光保护',grainAmount:'颗粒数量',grainSize:'颗粒大小',grainRoughness:'颗粒粗糙度',darks:'暗色调',lights:'亮色调',shadowSplit:'阴影分界',darkSplit:'中间分界',lightSplit:'高光分界',refineSaturation:'调整饱和度',sharpenAmount:'锐化数量',sharpenRadius:'锐化半径',sharpenDetail:'锐化细节',sharpenMasking:'锐化蒙版',noiseLuminance:'明亮度降噪',noiseLuminanceDetail:'明亮度细节',noiseLuminanceContrast:'明亮度对比度',noiseColor:'颜色降噪',noiseColorDetail:'颜色细节',noiseColorSmoothness:'颜色平滑度',profileDistortion:'配置文件畸变强度',profileVignetting:'配置文件暗角强度',distortion:'畸变',purpleAmount:'紫色边缘数量',purpleHueLow:'紫色色相下限',purpleHueHigh:'紫色色相上限',greenAmount:'绿色边缘数量',greenHueLow:'绿色色相下限',greenHueHigh:'绿色色相上限',vertical:'垂直校正',horizontal:'水平校正',rotate:'旋转',aspect:'长宽比例',scale:'缩放',offsetX:'水平偏移',offsetY:'垂直偏移',shadowTint:'阴影色调',redHue:'红原色色相',redSaturation:'红原色饱和度',greenHue:'绿原色色相',greenSaturation:'绿原色饱和度',blueHue:'蓝原色色相',blueSaturation:'蓝原色饱和度',hueShift:'色相调整',saturationShift:'饱和度调整',luminanceShift:'明亮度调整',hueRange:'色相范围',saturationRange:'饱和度范围',luminanceRange:'明亮度范围',hue:'色相',luminance:'明亮度',midtones:'中间调',global:'全局'};
const label=(key:string)=>zh.value?chinese[key]??key:key.replace(/([A-Z])/g,' $1').replace(/^./,c=>c.toUpperCase());
const curveGraph=computed(()=>{try{const table=cameraRawCurveTables(props.value.curve)[['rgb','red','green','blue'].indexOf(channel.value)];return 'M'+[...table].map((value,index)=>index/255*200+','+(1-value)*120).join(' L');}catch{return '';}});
const model=computed(()=>['light','color','effects'].includes(group.value)?props.value:props.value[group.value]);
const valid=computed(()=>{try{validateCameraRaw(props.value);return true;}catch{return false;}}),points=computed<any[]>(()=>props.value.curve[channel.value]);
function range(key:string){if(key==='exposure')return[-5,5,.05];if(key==='rotate')return[-45,45,.1];if(key==='sharpenAmount')return[0,150,1];if(/Hue(?:Low|High)$/.test(key))return[0,360,1];if(key==='shadowSplit')return[5,Math.min(90,props.value.curve.darkSplit-2),1];if(key==='darkSplit')return[props.value.curve.shadowSplit+2,props.value.curve.lightSplit-2,1];if(key==='lightSplit')return[props.value.curve.darkSplit+2,98,1];const positive=/^(grain|glow|sharpen|noise|profile)/.test(key)||['vignetteMidpoint','vignetteFeather','vignetteHighlights','purpleAmount','greenAmount'].includes(key);return[positive&&!['glowWarmth','glowRange','glowSpread'].includes(key)?0:-100,100,1];}
function reset(){const d:any=defaultCameraRaw();if(group.value==='mixer')props.options.visualizePoint=-1;if(['light','color','effects'].includes(group.value))for(const key of fields[group.value])props.value[key]=d[key];else props.value[group.value]=d[group.value];error.value='';emit('refresh');}
function autoWB(){const answer=props.source&&cameraRawAutoWhiteBalance(props.source);if(answer){Object.assign(props.value,answer);emit('refresh');}else error.value=zh.value?'无法从此图像确定白平衡。':'This image has no usable white-balance sample.';}
function hsl(rgb:number[]){const c=rgb.map(v=>v/255),max=Math.max(...c),min=Math.min(...c),delta=max-min,l=(max+min)/2;let h=0;if(delta){h=max===c[0]?(c[1]-c[2])/delta+(c[1]<c[2]?6:0):max===c[1]?(c[2]-c[0])/delta+2:(c[0]-c[1])/delta+4;h*=60;}return[h,delta?delta/(1-Math.abs(2*l-1)):0,l];}
let guideStart:number[]|undefined,drawGeneration=0,targetDrag:any,dragTimer:ReturnType<typeof setTimeout>|undefined,curveDrag:number|undefined;
function position(event:PointerEvent){const bounds=display.value!.getBoundingClientRect();return[Math.min(1,Math.max(0,(event.clientX-bounds.left)/bounds.width)),Math.min(1,Math.max(0,(event.clientY-bounds.top)/bounds.height))];}
function sampleStart(event:PointerEvent){if(!props.source||event.button!==0)return;if(sampleMode.value==='guide'){guideStart=position(event);display.value!.setPointerCapture(event.pointerId);}else if(sampleMode.value.startsWith('target')){const p=position(event),image=props.preview??props.source,rgb=cameraRawSample(image,p[0]*image.width,p[1]*image.height);if(rgb){const[h]=hsl(rgb.map((value:number)=>value*255));targetDrag={y:p[1],hue:h,tone:rgb[0]*.2126+rgb[1]*.7152+rgb[2]*.0722,settings:JSON.parse(JSON.stringify(props.value))};display.value!.setPointerCapture(event.pointerId);}}}
function sampleMove(event:PointerEvent){if(!props.source||!targetDrag)return;const delta=(targetDrag.y-position(event)[1])*props.source.height*.35,base=targetDrag.settings,limit=(v:number)=>Math.max(-100,Math.min(100,v));if(sampleMode.value==='targetCurve'){group.value='curve';const c=base.curve,tone=targetDrag.tone,key=tone<c.shadowSplit/100?'shadows':tone<c.darkSplit/100?'darks':tone<c.lightSplit/100?'lights':'highlights';props.value.curve[key]=limit(c[key]+delta);}else if(sampleMode.value==='targetPointCurve'){group.value='curve';const list=base.curve[channel.value],nearest=list.reduce((best:number,p:any,index:number)=>Math.abs(p.x-targetDrag.tone)<Math.abs(list[best].x-targetDrag.tone)?index:best,0);props.value.curve[channel.value][nearest].y=Math.max(0,Math.min(1,list[nearest].y+delta/100));}else{group.value='mixer';const key=sampleMode.value==='targetHue'?'hue':sampleMode.value==='targetSaturation'?'saturation':'luminance';for(const[index,center]of[0,30,60,120,180,240,270,300].entries()){const distance=Math.abs(targetDrag.hue-center),weight=Math.max(0,1-Math.min(distance,360-distance)/40);props.value.mixer[key][index]=limit(base.mixer[key][index]+delta*weight);}}clearTimeout(dragTimer);dragTimer=setTimeout(()=>emit('refresh'),100);}
function sampleEnd(event:PointerEvent){if(!props.source||event.button!==0)return;if(targetDrag){sampleMove(event);targetDrag=undefined;clearTimeout(dragTimer);emit('refresh');return;}const p=position(event),sampleImage=sampleMode.value==='point'&&!before.value?(props.preview??props.source):props.source,sampled=cameraRawSample(sampleImage,p[0]*sampleImage.width,p[1]*sampleImage.height),rgb=sampled?.map((value:number)=>value*255);if(sampleMode.value==='guide'){if(guideStart&&props.value.geometry.guides.length<8&&Math.hypot(p[0]-guideStart[0],p[1]-guideStart[1])>.01){props.value.geometry.upright='Guided';props.value.geometry.guides.push({startX:+guideStart[0].toFixed(4),startY:+(1-guideStart[1]).toFixed(4),endX:+p[0].toFixed(4),endY:+(1-p[1]).toFixed(4)});emit('refresh');}guideStart=undefined;return;}if(!rgb)return;readout.value='RGB '+rgb.map((value:number)=>Math.round(value)).join(', ');if(sampleMode.value==='whiteBalance'){const answer=cameraRawWhiteBalance(rgb.map(v=>v/255));if(answer)Object.assign(props.value,answer);}else if(sampleMode.value==='point'){if(props.value.mixer.points.length>=8&&!(replacePoint.value&&props.value.mixer.points[point.value]))return;const[h,s,l]=hsl(rgb),sample:any={hue:h,saturation:s,luminance:l,hueShift:0,saturationShift:0,luminanceShift:0,hueRange:30,saturationRange:.4,luminanceRange:.4};if(replacePoint.value&&props.value.mixer.points[point.value]){for(const key of ['hueShift','saturationShift','luminanceShift'])sample[key]=props.value.mixer.points[point.value][key];props.value.mixer.points[point.value]=sample;}else{props.value.mixer.points.push(sample);point.value=props.value.mixer.points.length-1;}group.value='mixer';}else if(sampleMode.value==='defringe'){const[h]=hsl(rgb),green=Math.abs(h-90)<=Math.abs(h-290);Object.assign(props.value.optics,green?{greenHueLow:Math.max(0,h-25),greenHueHigh:Math.min(360,h+25),greenAmount:props.value.optics.greenAmount||50}:{purpleHueLow:Math.max(0,h-25),purpleHueHigh:Math.min(360,h+25),purpleAmount:props.value.optics.purpleAmount||50});group.value='optics';}emit('refresh');}
function curveClick(event:PointerEvent){const bounds=(event.currentTarget as SVGElement).getBoundingClientRect(),x=Math.min(.99,Math.max(.01,(event.clientX-bounds.left)/bounds.width)),y=Math.min(1,Math.max(0,1-(event.clientY-bounds.top)/bounds.height));if(points.value.length<32&&!points.value.some((p:any)=>Math.abs(p.x-x)<.01)){points.value.push({x,y});points.value.sort((a:any,b:any)=>a.x-b.x);emit('refresh');}}
function curveDown(event:PointerEvent,index:number){curveDrag=index;(event.currentTarget as SVGElement).setPointerCapture(event.pointerId);}
function curveMove(event:PointerEvent){if(curveDrag===undefined)return;const bounds=(event.currentTarget as SVGElement).getBoundingClientRect(),index=curveDrag,p=points.value[index];if(index>0&&index<points.value.length-1)p.x=Math.max(points.value[index-1].x+.01,Math.min(points.value[index+1].x-.01,(event.clientX-bounds.left)/bounds.width));p.y=Math.max(0,Math.min(1,1-(event.clientY-bounds.top)/bounds.height));}
function curveEnd(){if(curveDrag===undefined)return;curveDrag=undefined;emit('refresh');}
function presetCurve(strong=0){props.value.curve[channel.value]=strong?[{x:0,y:0},{x:.25,y:strong===1?.18:.10},{x:.75,y:strong===1?.82:.90},{x:1,y:1}]:[{x:0,y:0},{x:1,y:1}];emit('refresh');}
async function draw(){const image=before.value?props.source:props.preview??props.source,own=++drawGeneration;if(!image||!display.value)return;const bitmap=await createImageBitmap(new ImageData(new Uint8ClampedArray(image.data),image.width,image.height));try{if(own!==drawGeneration||!display.value)return;const canvas=display.value,scale=Math.min(8,600/image.width,240/image.height);canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d')!.imageSmoothingEnabled=scale<1;canvas.getContext('2d')!.drawImage(bitmap,0,0,canvas.width,canvas.height);}finally{bitmap.close();}drawScope(image);}
function drawScope(image:any){const canvas=scope.value;if(!canvas)return;canvas.width=256;canvas.height=100;const ctx=canvas.getContext('2d')!;ctx.fillStyle='#111';ctx.fillRect(0,0,256,100);const stride=Math.max(1,Math.floor(image.width*image.height/100000)),bins=[new Uint32Array(256),new Uint32Array(256),new Uint32Array(256)];for(let pixel=0;pixel<image.width*image.height;pixel+=stride){const i=pixel*4;if(!image.data[i+3])continue;for(let c=0;c<3;c++)bins[c][image.data[i+c]]++;if(scopeMode.value==='vectorscope'){const[h,s]=hsl([...image.data.slice(i,i+3)]),angle=h*Math.PI/180;ctx.fillStyle=`rgba(${image.data[i]},${image.data[i+1]},${image.data[i+2]},.2)`;ctx.fillRect(128+Math.cos(angle)*s*45,50-Math.sin(angle)*s*45,1,1);}}if(scopeMode.value==='histogram')for(let c=0;c<3;c++){const max=Math.max(1,...bins[c]);ctx.strokeStyle=['#ff7070','#70dd80','#809cff'][c];ctx.beginPath();for(let x=0;x<256;x++){const y=100-bins[c][x]/max*98;if(x)ctx.lineTo(x,y);else ctx.moveTo(x,y);}ctx.stroke();}else{ctx.strokeStyle='#aaa';ctx.beginPath();ctx.arc(128,50,45,0,Math.PI*2);ctx.stroke();}}
watch(()=>[props.source,props.preview,before.value,scopeMode.value],()=>{void nextTick(draw).catch(()=>{error.value=zh.value?'预览暂时不可用，请重试。':'Preview is unavailable. Try again.';});});onUnmounted(()=>{drawGeneration++;clearTimeout(dragTimer);});onMounted(()=>{emit('refresh');});
</script>
<template><section class="camera-raw-controls" data-testid="camera-raw-controls"><div class="raw-preview"><div class="raw-image"><canvas ref="display" data-testid="raw-sample" @pointerdown="sampleStart" @pointermove="sampleMove" @pointerup="sampleEnd" @pointercancel="targetDrag=undefined;guideStart=undefined"></canvas><svg v-if="sampleMode==='guide'&&source" :viewBox="`0 0 ${source.width} ${source.height}`" preserveAspectRatio="none"><line v-for="(line,index) in value.geometry.guides" :key="index" :x1="line.startX*source.width" :y1="(1-line.startY)*source.height" :x2="line.endX*source.width" :y2="(1-line.endY)*source.height" stroke="#5ff" :stroke-width="source.width/(display?.width||source.width)"/></svg></div><canvas ref="scope" :aria-label="zh?'预览抽样示波器':'Sampled preview scope'" role="img"></canvas></div><div class="button-row"><label><input v-model="before" type="checkbox">{{zh?'原图对比':'Before'}}</label><select v-model="scopeMode" :aria-label="zh?'示波器':'Scope'"><option value="histogram">{{zh?'直方图':'Histogram'}}</option><option value="vectorscope">{{zh?'矢量示波器':'Vectorscope'}}</option></select><select v-model="sampleMode" :aria-label="zh?'图像取样工具':'Image sampling tool'"><option value="whiteBalance">{{zh?'白平衡吸管':'White balance eyedropper'}}</option><option value="point">{{zh?'取样点颜色':'Sample point color'}}</option><option value="defringe">{{zh?'取样去边颜色':'Sample defringe color'}}</option><option value="targetCurve">{{zh?'拖动调整参数曲线':'Drag parametric curve'}}</option><option value="targetPointCurve">{{zh?'拖动调整点曲线':'Drag point curve'}}</option><option value="targetHue">{{zh?'拖动调整色相':'Drag color hue'}}</option><option value="targetSaturation">{{zh?'拖动调整饱和度':'Drag color saturation'}}</option><option value="targetLuminance">{{zh?'拖动调整明亮度':'Drag color luminance'}}</option><option value="guide">{{zh?'拖动添加几何参考线':'Drag a geometry guide'}}</option></select><span>{{readout}}</span></div><p v-if="error||!valid" role="alert">{{error||(zh?'参数无效，请检查曲线和数值范围。':'Check the curve points and numeric ranges.')}}</p><div class="raw-groups" :aria-label="zh?'调节组':'Adjustment group'"><button v-for="[id,en,cn] in groups" :key="id" type="button" :data-testid="'raw-group-'+id" :aria-pressed="group===id" @click="group=id">{{zh?cn:en}}</button></div><div class="button-row"><label><input v-model="value.enabled[group]" type="checkbox" @change="emit('refresh')">{{zh?'启用此组':'Enable this group'}}</label><button type="button" @click="reset">{{zh?'重置此组':'Reset this group'}}</button><button v-if="group==='color'" type="button" :disabled="!source" data-testid="raw-auto-wb" @click="autoWB">{{zh?'自动白平衡':'Auto white balance'}}</button></div><fieldset :disabled="!value.enabled[group]">
  <div class="style-fields"><label v-for="key in fields[group]??[]" :key="key">{{label(key)}}<input v-model.number="model[key]" :data-testid="'raw-'+group+'-'+key" type="number" :min="range(key)[0]" :max="range(key)[1]" :step="range(key)[2]" @change="emit('refresh')"></label></div>
  <template v-if="group==='effects'"><label>{{zh?'辉光样式':'Glow style'}}<select v-model="value.glowStyle" @change="emit('refresh')"><option value="Diffusion">{{zh?'扩散':'Diffusion'}}</option><option value="Bloom">{{zh?'泛光':'Bloom'}}</option><option value="Halation">{{zh?'光晕':'Halation'}}</option></select></label><label>{{zh?'暗角样式':'Vignette style'}}<select v-model="value.vignetteStyle" @change="emit('refresh')"><option value="Highlight Priority">{{zh?'高光优先':'Highlight Priority'}}</option><option value="Color Priority">{{zh?'颜色优先':'Color Priority'}}</option><option value="Paint Overlay">{{zh?'涂色叠加':'Paint Overlay'}}</option></select></label></template>
  <template v-if="group==='curve'"><select v-model="channel" :aria-label="zh?'曲线通道':'Curve channel'"><option>rgb</option><option>red</option><option>green</option><option>blue</option></select><div class="button-row"><button type="button" @click="presetCurve()">{{zh?'线性':'Linear'}}</button><button type="button" @click="presetCurve(1)">{{zh?'中等对比':'Medium contrast'}}</button><button type="button" @click="presetCurve(2)">{{zh?'强对比':'Strong contrast'}}</button></div><svg class="raw-curve" viewBox="0 0 200 120" data-testid="raw-curve" @pointerdown.prevent="curveClick" @pointermove="curveMove" @pointerup="curveEnd" @pointercancel="curveEnd"><path :d="curveGraph"/><circle v-for="(p,index) in points" :key="index" :cx="p.x*200" :cy="(1-p.y)*120" r="3" @pointerdown.stop.prevent="curveDown($event,index)"/></svg><div v-for="(p,index) in points" :key="index" class="button-row"><label>X<input v-model.number="p.x" type="number" min="0" max="1" step=".01" :disabled="index===0||index===points.length-1" @change="emit('refresh')"></label><label>Y<input v-model.number="p.y" type="number" min="0" max="1" step=".01" @change="emit('refresh')"></label><button v-if="index>0&&index<points.length-1" type="button" @click="points.splice(index,1);emit('refresh')">−</button></div></template>
  <template v-if="group==='mixer'"><select v-model.number="family" :aria-label="zh?'颜色范围':'Color family'"><option v-for="(name,index) in (zh?['红','橙','黄','绿','青','蓝','紫','洋红']:['Reds','Oranges','Yellows','Greens','Aquas','Blues','Purples','Magentas'])" :key="index" :value="index">{{name}}</option></select><div class="style-fields"><label v-for="key in ['hue','saturation','luminance']" :key="key">{{label(key)}}<input v-model.number="value.mixer[key][family]" type="number" min="-100" max="100" @change="emit('refresh')"></label></div><p>{{zh?'在图像上取样点颜色，最多 8 个。':'Sample point colors on the image (up to 8).'}}</p><select v-if="value.mixer.points.length" v-model.number="point" :aria-label="zh?'点颜色':'Point color'"><option v-for="(_,index) in (value.mixer.points as any[])" :key="index" :value="index">{{index+1}}</option></select><template v-if="value.mixer.points[point]"><label><input v-model="replacePoint" type="checkbox">{{zh?'取样替换当前点颜色':'Resample the selected point'}}</label><div class="style-fields"><label v-for="key in ['hueShift','saturationShift','luminanceShift','hueRange','saturationRange','luminanceRange']" :key="key">{{label(key)}}<input v-model.number="value.mixer.points[point][key]" type="number" :min="key.endsWith('Shift')?-100:key==='hueRange'?5:.05" :max="key.endsWith('Shift')?100:key==='hueRange'?180:1" :step="key.endsWith('Range')&&key!=='hueRange'?.01:1" @change="emit('refresh')"></label></div><button type="button" @click="options.visualizePoint=options.visualizePoint===point?-1:point;emit('refresh')">{{zh?'查看点颜色范围':'Visualize point range'}}</button><button type="button" @click="value.mixer.points.splice(point,1);point=0;options.visualizePoint=-1;emit('refresh')">{{zh?'删除点颜色':'Remove point'}}</button></template></template>
  <template v-if="group==='grading'"><select v-model="wheel" :aria-label="zh?'分色范围':'Grading range'"><option v-for="key in ['shadows','midtones','highlights','global']" :key="key" :value="key">{{label(key)}}</option></select><div class="style-fields"><label v-for="key in ['hue','saturation','luminance']" :key="key">{{label(key)}}<input v-model.number="value.grading[wheel][key]" type="number" :min="key==='luminance'?-100:0" :max="key==='hue'?360:100" @change="emit('refresh')"></label><label>{{zh?'混合':'Blending'}}<input v-model.number="value.grading.blending" type="number" min="0" max="100" @change="emit('refresh')"></label><label>{{zh?'平衡':'Balance'}}<input v-model.number="value.grading.balance" type="number" min="-100" max="100" @change="emit('refresh')"></label></div></template>
  <template v-if="group==='optics'"><label><input v-model="value.optics.removeChromaticAberration" type="checkbox" @change="emit('refresh')">{{zh?'去除色差':'Remove chromatic aberration'}}</label><label><input v-model="value.optics.enableLensProfile" type="checkbox" @change="emit('refresh')">{{zh?'启用通用镜头校正':'Enable generic lens correction'}}</label></template>
  <template v-if="group==='geometry'"><select v-model="value.geometry.upright" :aria-label="zh?'自动校正':'Upright'" @change="emit('refresh')"><option value="Off">{{zh?'关闭':'Off'}}</option><option value="Guided">{{zh?'引导式':'Guided'}}</option></select><select v-model="value.geometry.projection" :aria-label="zh?'投影':'Projection'" @change="emit('refresh')"><option value="Perspective">{{zh?'透视':'Perspective'}}</option><option value="Rectilinear">{{zh?'直线':'Rectilinear'}}</option></select><label><input v-model="value.geometry.constrainCrop" type="checkbox" @change="emit('refresh')">{{zh?'约束裁剪':'Constrain crop'}}</label><button type="button" @click="value.geometry.guides=[];emit('refresh')">{{zh?'清除参考线':'Clear guides'}}</button><div v-for="(line,index) in value.geometry.guides" :key="index" class="style-fields"><label v-for="key in ['startX','startY','endX','endY']" :key="key">{{key}}<input v-model.number="line[key]" type="number" min="0" max="1" step=".01" @change="emit('refresh')"></label></div></template>
  <label v-if="group==='calibration'">{{zh?'处理版本':'Process version'}}<select v-model.number="value.calibration.process" :aria-label="zh?'处理版本':'Process version'" data-testid="raw-calibration-process" @change="emit('refresh')"><option v-for="version in 6" :key="version" :value="version">{{version}}</option></select></label>
  </fieldset><div class="button-row raw-preview-options"><label>{{zh?'剪切预览':'Clipping preview'}}<select v-model.number="options.clipping" @change="emit('refresh')"><option :value="0">{{zh?'关闭':'Off'}}</option><option :value="1">{{zh?'高光':'Highlights'}}</option><option :value="2">{{zh?'阴影':'Shadows'}}</option></select></label><label><input v-model="options.overlayShadows" type="checkbox" @change="emit('refresh')">{{zh?'阴影溢出提示':'Shadow warning'}}</label><label><input v-model="options.overlayHighlights" type="checkbox" @change="emit('refresh')">{{zh?'高光溢出提示':'Highlight warning'}}</label><label><input v-model="options.sharpenMask" type="checkbox" @change="emit('refresh')">{{zh?'锐化蒙版预览':'Sharpen mask preview'}}</label></div><small>{{zh?'预览辅助显示不会应用到图层。':'Preview aids are never applied to the layer.'}}</small></section></template>
<style scoped>.camera-raw-controls{margin:10px 0;max-width:760px}.raw-groups{display:flex;flex-wrap:wrap;gap:4px;margin:8px 0}.raw-groups button[aria-pressed=true]{background: var(--selection-solid);color: var(--on-accent)}.camera-raw-controls fieldset{border: 1px solid var(--border-strong);padding:10px;max-height:34vh;overflow:auto}.raw-preview{display:flex;align-items:center;gap:12px}.raw-image{position:relative;display:inline-block;max-width:75%}.raw-image canvas{display:block;max-width:100%;max-height:240px;touch-action:none;background:repeating-conic-gradient(#555 0 25%,#777 0 50%) 0/12px 12px}.raw-image svg{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}.raw-preview>canvas{width:25%;height:auto;aspect-ratio:256/100;object-fit:contain}.camera-raw-controls .button-row>label{display:flex;align-items:center;gap:4px}.raw-curve{width:200px;height:120px;background: var(--surface);cursor:crosshair}.raw-curve path{fill:none;stroke:var(--text)}.raw-curve circle{fill:var(--accent)}.raw-preview-options{margin-top:8px}.camera-raw-controls p[role=alert]{color: var(--error)}</style>
